class Solution {
    public boolean equalFrequency(String word) {
        int[] freq = new int[26];
        for (char c : word.toCharArray()) {
            freq[c - 'a']++;
        }

        for (int i = 0; i < 26; i++) {
            if (freq[i] == 0) {
                continue;
            }
            freq[i]--;
            if (allPositiveFrequenciesEqual(freq)) {
                return true;
            }
            freq[i]++;
        }
        return false;
    }

    private boolean allPositiveFrequenciesEqual(int[] freq) {
        int target = 0;
        for (int count : freq) {
            if (count == 0) {
                continue;
            }
            if (target == 0) {
                target = count;
            } else if (count != target) {
                return false;
            }
        }
        return true;
    }
}

class Solution {
    public boolean equalFrequency(String word) {
        int[] freq = new int[26];
        for (char ch : word.toCharArray()) {
            freq[ch - 'a']++;
        }

        int f1 = 0, c1 = 0, f2 = 0, c2 = 0;
        for (int f : freq) {
            if (f == 0) {
                continue;
            }
            if (f1 == 0 || f == f1) {
                if (f1 == 0) {
                    f1 = f;
                }
                c1++;
            } else if (f2 == 0 || f == f2) {
                if (f2 == 0) {
                    f2 = f;
                }
                c2++;
            } else {
                return false;
            }
        }

        if (f2 == 0) {
            return f1 == 1 || c1 == 1;
        }
        if (f1 > f2) {
            int tmpFrequency = f1;
            f1 = f2;
            f2 = tmpFrequency;
            int tmpCount = c1;
            c1 = c2;
            c2 = tmpCount;
        }
        return (f1 == 1 && c1 == 1) || (f2 == f1 + 1 && c2 == 1);
    }
}

import java.util.*;

class Solution {
    public boolean equalFrequency(String word) {
        int[] freq = new int[26];
        for (char c : word.toCharArray()) {
            freq[c - 'a']++;
        }

        List<Integer> counts = new ArrayList<>();
        for (int count : freq) {
            if (count > 0) {
                counts.add(count);
            }
        }
        Collections.sort(counts);

        int size = counts.size();
        if (size == 1) {
            return true;
        }
        boolean removeSingleLow = counts.get(0) == 1
                && counts.get(1).equals(counts.get(size - 1));
        boolean reduceSingleHigh = counts.get(size - 1) == counts.get(size - 2) + 1
                && counts.get(0).equals(counts.get(size - 2));
        return removeSingleLow || reduceSingleHigh;
    }
}

class Solution {
    public boolean equalFrequency(String word) {
        for (int removed = 0; removed < word.length(); removed++) {
            int[] freq = new int[26];
            for (int i = 0; i < word.length(); i++) {
                if (i != removed) {
                    freq[word.charAt(i) - 'a']++;
                }
            }
            if (equalPositiveFrequencies(freq)) {
                return true;
            }
        }
        return false;
    }

    private boolean equalPositiveFrequencies(int[] freq) {
        int target = 0;
        for (int count : freq) {
            if (count == 0) {
                continue;
            }
            if (target == 0) {
                target = count;
            } else if (count != target) {
                return false;
            }
        }
        return true;
    }
}
